draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(W, H);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 20 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(50, H/2);
  ctx.lineTo(50, H/2 + 50 * Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W-50, H/2);
  ctx.lineTo(W-50, H/2 + 50 * Math.cos(t + Math.PI));
  ctx.stroke();
  ctx.restore();
}
